1	// Land a task's delivered pull request under the REPO's delivery settings — the
2	// single home for the auto-merge nuances every PR-delivering task shares. These
3	// helpers were built inside the baselining worker (#455/#565/#649/#677/#690);
4	// they live here because the other `merged-pr` tasks hit the identical failure
5	// shapes (an arm rejected "clean status" on an ungated base stranding a green PR
6	// forever), and two copies of this precedence is exactly the drift the corpus
7	// forbids.
8	//
9	// The contract that keeps tasks simple: a task declares only its outcome CEILING
10	// (`expected_outcome: 'merged-pr'` — it MAY land a PR). Whether the PR actually
11	// lands unreviewed is the MEMBER REPO's call — `dailyClaudiniteUpdatesRequirePrReview`
12	// in its settings file, where `true` degrades every merged-pr task to open-pr
13	// (member config wins, per-project-scheduling DESIGN §1). Tasks stay
14	// unaware of that setting by construction: they hand their PR to landDelivery()
15	// (directly, or through deliver-generated.mjs) and the repo-shape nuances stay
16	// here:
17	//
18	//   - `review` member          → the PR is opened and LEFT — never armed, never merged.
19	//   - no pull_request CI at all → MERGE directly. GitHub's auto-merge is a queue
20	//     for checks; with nothing to queue behind, the arm is rejected ("Pull
21	//     request is in clean status") every time, and while that rejection was
22	//     swallowed a repo that asked for auto-merge got no merge at all.
23	//   - CI present, but the base branch REQUIRES nothing → the arm is equally
24	//     doomed (same clean-status rejection, #677): skip it, wait for this run's
25	//     own dispatched evidence, and land on it (verify-then-merge).
26	//   - a base gate present — or unreadable, which is never read as absent → ARM,
27	//     with the landing poll as fallback when the arm is rejected (auto-merge
28	//     disabled repo-side, or a pull_request run parked at `action_required`).
29	//
30	// A branch pushed and a PR opened over the Action's GITHUB_TOKEN emit no
31	// pull_request run of their own (GitHub's recursion guard, #565), so
32	// landDelivery also STARTS the PR's checks via workflow_dispatch before deciding
33	// anything — the checks an arm would wait on must exist to conclude.
34	//
35	// The AGENT lane (executor subagents, MCP writes) cannot run this module; its
36	// prose twin is `deliver-pr.md` beside this file, and the two must keep saying
37	// the same thing — a nuance changed here changes there in the same commit.
38	//
39	// DISPOSAL lives here too (`openDeliveredPull` / `disposeOpenPull`). It began as
40	// baselining's private close-and-recut, kept in that worker while it was the only
41	// task that re-cut a per-cycle branch. The update flows re-cut one exactly the same
42	// way, and #787 is what the second copy would have cost: the update runner promised
43	// "leaving it open for the next run to dispose of" with no code anywhere that could
44	// keep the promise, so a PR its cycle could not land was superseded by a duplicate
45	// the next cycle opened instead. One precedence, one home.
46	
47	const API = 'https://api.github.com';
48	
49	async function gh(token, path, { method = 'GET', body } = {}) {
50	  const res = await fetch(`${API}${path}`, {
51	    method,
52	    headers: {
53	      authorization: `Bearer ${token}`,
54	      accept: 'application/vnd.github+json',
55	      'x-github-api-version': '2022-11-28',
56	      ...(body ? { 'content-type': 'application/json' } : {}),
57	    },
58	    body: body ? JSON.stringify(body) : undefined,
59	  });
60	  let json = null;
61	  try { json = await res.json(); } catch { /* empty body */ }
62	  return { status: res.status, json };
63	}
64	
65	// --- the member's delivery preference ----------------------------------------
66	
67	// The member's delivery preference, normalized. `push`/`auto` → auto-merge and
68	// `pr` → review are the permanent legacy aliases (the maintenance-lane tolerance);
69	// anything else is invalid (null) and fails the run rather than guessing.
70	export function normalizeDelivery(raw) {
71	  const v = String(raw ?? '').trim();
72	  if (v === 'auto-merge' || v === 'auto' || v === 'push') return 'auto-merge';
73	  if (v === 'review' || v === 'pr') return 'review';
74	  return null;
75	}
76	
77	// The default a repo gets when it never declared one.
78	export const DEFAULT_DELIVERY = 'auto-merge';
79	
80	// @deprecated — the `maintenance.delivery` resolution, kept callable for the
81	// fielded workers that still import it (an `updates/*`-class surface: a member's
82	// vendored worker is a cycle behind the flows that rewrote its declaration). New
83	// callers ask `deliveryFor` below, which reads the current key.
84	//
85	// `maintenance.delivery` was always EXPLICIT — but a key that is simply absent is
86	// DRIFT, not an error. A repo adopted before the key existed, or one whose key
87	// was hand-removed, would otherwise fail its scheduled tasks every night forever
88	// with nothing that could ever fix it. So: resolve to the default and carry on —
89	// `materialize: true` tells the one caller that CAN write the repair to do so.
90	//
91	// An UNRECOGNIZED value is a different thing entirely: someone wrote an intent
92	// this code cannot honour, and silently substituting a default would deliver
93	// the opposite of what they asked for. That still fails the run (delivery: null).
94	export function resolveDelivery(raw) {
95	  if (raw == null || String(raw).trim() === '') {
96	    return { delivery: DEFAULT_DELIVERY, materialize: true };
97	  }
98	  return { delivery: normalizeDelivery(raw), materialize: false };
99	}
100	
101	// @deprecated with `resolveDelivery` above, and kept callable for the same reason.
102	export function deliveryFromChecks(text) {
103	  let parsed = null;
104	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
105	  return resolveDelivery(parsed?.maintenance?.delivery);
106	}
107	
108	// THE MEMBER'S DELIVERY, from its parsed settings. One override, one direction:
109	// `dailyClaudiniteUpdatesRequirePrReview: true` leaves the PR for a human, and
110	// anything else — the key absent, which is the normal shape — lands it. That
111	// asymmetry is the point of #1252: every member wanted the same thing, so the
112	// setting materialized into every declaration said nothing, and the one repo that
113	// wants review is the one that should have to say so.
114	//
115	// The retired `maintenance.delivery` is read underneath for a member the rename
116	// record has not reached. Unparsable or absent settings resolve like an absent
117	// key — auto-merge, not failure: the file's integrity is check_the_world's
118	// problem, not the delivery step's.
119	export function deliveryFor(settings) {
120	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === true) return 'review';
121	  if (settings?.dailyClaudiniteUpdatesRequirePrReview === undefined
122	      && normalizeDelivery(settings?.maintenance?.delivery) === 'review') return 'review';
123	  return DEFAULT_DELIVERY;
124	}
125	
126	// The same, from the raw TEXT of a settings file — the shape a caller reading the
127	// file off a git blob has in hand.
128	export function deliveryForText(text) {
129	  let parsed = null;
130	  try { parsed = JSON.parse(text ?? 'null'); } catch { /* unreadable → absent */ }
131	  return deliveryFor(parsed);
132	}
133	
134	// --- CI dispatch on the delivered PR (#565) -----------------------------------
135	// The GITHUB_TOKEN push/PR-open emits no pull_request run (GitHub's recursion
136	// guard), so the delivery starts the PR's checks itself: dispatch every workflow
137	// that WOULD have run on pull_request and CAN be dispatched.
138	//
139	// "Suppresses" is only half true, and the other half is #455/#205/#95: on some
140	// members GitHub CREATES the pull_request run and parks it at `action_required`
141	// awaiting an approval nobody clicks. The dispatch above still supplies the real
142	// green, but the parked run is what auto-merge refuses over — which is why
143	// arming is not the end of the story and pullDisposition exists.
144	//
145	// Reading the triggers is a best-effort TEXTUAL scan of a workflow's top-level
146	// `on:` block (no YAML parser in the corpus). It covers the shapes workflows
147	// actually use: a block map of trigger keys (with or without nested config), the
148	// inline scalar, and the inline list.
149	export function workflowTriggers(yaml) {
150	  const lines = String(yaml ?? '').split('\n');
151	  const onAt = lines.findIndex((l) => /^(['"]?)on\1\s*:/.test(l));
152	  if (onAt === -1) return [];
153	  const inline = lines[onAt].replace(/^(['"]?)on\1\s*:/, '').replace(/#.*$/, '').trim();
154	  if (inline) return inline.replace(/[[\]]/g, '').split(',').map((s) => s.trim()).filter(Boolean);
155	  const triggers = [];
156	  let childIndent = null;
157	  for (let i = onAt + 1; i < lines.length; i += 1) {
158	    const line = lines[i];
159	    if (!line.trim() || line.trim().startsWith('#')) continue;
160	    const indent = line.length - line.trimStart().length;
161	    if (indent === 0) break;                        // next top-level key — on: is done
162	    childIndent = childIndent ?? indent;            // first child fixes the trigger level
163	    if (indent !== childIndent) continue;           // nested config under a trigger
164	    const m = /^([A-Za-z_]+)\s*:/.exec(line.trim());
165	    if (m) triggers.push(m[1]);
166	  }
167	  return triggers;
168	}
169	
170	// The dispatch plan over the repo's workflow files ({name, content} each):
171	// `dispatch` — runs on pull_request AND carries workflow_dispatch (start these);
172	// `missing`  — runs on pull_request but CANNOT be dispatched (name these in the
173	// log: adding `workflow_dispatch:` to that file's `on:` is the owner's one-line
174	// fix, and silence here would read as "no CI expected" when CI was expected).
175	// A workflow with no pull_request trigger is never touched — dispatchable-but-
176	// unrelated workflows (a release orchestrator, say) must not fire on a delivery.
177	export function ciDispatchPlan(files) {
178	  const dispatch = [];
179	  const missing = [];
180	  for (const { name, content } of files ?? []) {
181	    const triggers = workflowTriggers(content);
182	    if (!triggers.includes('pull_request')) continue;
183	    (triggers.includes('workflow_dispatch') ? dispatch : missing).push(name);
184	  }
185	  return { dispatch, missing };
186	}
187	
188	// The I/O half of the CI dispatch: read the workflow files as they exist ON THE
189	// DELIVERED BRANCH (the delivery may itself have changed them), plan with
190	// ciDispatchPlan, POST a dispatch per selected workflow, and log every outcome —
191	// a silent no-checks PR is exactly the failure mode this exists to close. Needs
192	// the scheduler workflow's `actions: write` (a read-only token 403s the POST
193	// silently — the store-release lesson).
194	// Returns { dispatch, missing, started }: `dispatch`/`missing` are the PLAN
195	// (what the tree says should run), `started` the dispatches GitHub actually
196	// accepted (204). The landing poll must wait only on `started` — a POST that
197	// 403'd (the scheduler workflow missing `actions: write`, the canon's own copy
198	// on 2026-08-08) starts nothing, and counting the plan had the poll waiting for
199	// a run that could never come.
200	export async function dispatchCiRuns({ token, repo, branch, log = console.log }) {
201	  const ref = encodeURIComponent(branch);
202	  const { json: dir } = await gh(token, `/repos/${repo}/contents/.github/workflows?ref=${ref}`);
203	  const files = [];
204	  for (const entry of Array.isArray(dir) ? dir : []) {
205	    if (!/\.ya?ml$/.test(entry.name ?? '')) continue;
206	    const { json } = await gh(token, `/repos/${repo}/contents/.github/workflows/${entry.name}?ref=${ref}`);
207	    files.push({ name: entry.name, content: json?.content ? Buffer.from(json.content, 'base64').toString('utf8') : '' });
208	  }
209	  const { dispatch, missing } = ciDispatchPlan(files);
210	  for (const name of missing) {
211	    log(`${name} runs on pull_request but has no workflow_dispatch trigger — `
212	      + 'cannot start it on the delivered PR; add `workflow_dispatch:` under its `on:` to let the delivery run it');
213	  }
214	  if (!dispatch.length && !missing.length) {
215	    log('no pull_request-triggered workflow — the delivered PR has no checks to wait for');
216	  }
217	  const started = [];
218	  for (const name of dispatch) {
219	    const res = await gh(token, `/repos/${repo}/actions/workflows/${name}/dispatches`, {
220	      method: 'POST', body: { ref: branch },
221	    });
222	    if (res.status === 204) { started.push(name); log(`dispatched ${name} on ${branch} — the delivered PR gets its checks`); }
223	    else {
224	      log(`could not dispatch ${name} on ${branch} (${res.status})`
225	        + (res.status === 403 ? ' — the scheduler workflow needs `actions: write` (a read token 403s this POST silently)' : ''));
226	    }
227	  }
228	  return { dispatch, missing, started };
229	}
230	
231	// --- opening the PR ------------------------------------------------------------
232	
233	// Why the PR-open POST must be status-checked, as a pure predicate: null when
234	// the PR was created, else the message to fail on.
235	//
236	// This is the one call whose silent failure is invisible AND self-perpetuating:
237	// a cycle that pushes its branch but fails to open the PR leaves nothing for the
238	// next cycle to find, branches pile up nightly, and the run still reports `ok`
239	// because nothing read the status. The usual cause is repo-level and invisible
240	// from here — "Allow GitHub Actions to create and approve pull requests" is off
241	// and the POST 403s — so the message names that remedy rather than leaving a
242	// bare status code.
243	export function pullCreateError(status, json) {
244	  if (status === 201 && json?.number) return null;
245	  const detail = json?.message ?? `HTTP ${status}`;
246	  return `${detail} — if this is the Actions PR permission, enable Settings → Actions`
247	    + ' → General → "Allow GitHub Actions to create and approve pull requests"';
248	}
249	
250	// --- the delivery decision -------------------------------------------------------
251	
252	// How an `auto-merge` member's PR actually lands, given whether this repo has any
253	// pull_request-triggered workflow at all.
254	//
255	// GitHub's auto-merge is a QUEUE FOR CHECKS. On a repo with no PR CI there is
256	// nothing to queue behind: the mutation is rejected ("Pull request is in clean
257	// status"), and since the failure was swallowed the PR sat open forever — a repo
258	// that asked for `auto-merge` got no merge at all. Seven of twelve consumers were
259	// in exactly that shape (no `pull_request` trigger anywhere in .github/workflows).
260	//
261	// So: no CI to wait for → MERGE IT, which is what `auto-merge` meant all along.
262	//
263	// `hasPrCi` comes from ciDispatchPlan over the branch's own workflow files —
264	// `dispatch` (startable) plus `missing` (PR-triggered but not dispatchable). Both
265	// empty means no workflow anywhere runs on a pull_request, so no check will ever
266	// appear. That is a fact about the tree, not a race against checks registering.
267	//
268	// `gate` is what the BASE BRANCH requires (classifyMergeGate) — the thing
269	// GitHub's auto-merge actually queues behind. CI existing was the wrong
270	// predicate (#677): on an unprotected base the PR is mergeable the whole time
271	// its checks run, so `enablePullRequestAutoMerge` is rejected "clean status"
272	// every cycle no matter how green — arming there is doomed, and the delivery
273	// goes straight to verify-then-land instead. `unknown` arms: a gate we could
274	// not see is never merged past.
275	export function deliveryAction({ delivery, hasPrCi, gate = 'unknown' }) {
276	  if (delivery !== 'auto-merge') return 'none';
277	  if (!hasPrCi) return 'merge';
278	  return gate === 'absent' ? 'land' : 'arm';
279	}
280	
281	// What the base branch requires before a merge, from the two reads the Action's
282	// GITHUB_TOKEN can make: the branch's `protected` flag and the ruleset rules
283	// that apply to it (deliberately NOT /branches/{base}/protection, which wants
284	// admin). Rule types that queue a PR gate it; rules about pushes and deletions
285	// do not. An unreadable answer is UNKNOWN, never absent — unknown assumes a
286	// gate, so the caller arms rather than merging past a gate it cannot see.
287	const GATING_RULE_TYPES = ['pull_request', 'required_status_checks', 'merge_queue', 'required_deployments'];
288	export function classifyMergeGate({ branchStatus, branchJson, rulesStatus, rulesJson }) {
289	  if (branchStatus !== 200 || typeof branchJson?.protected !== 'boolean') return 'unknown';
290	  if (branchJson.protected) return 'present';
291	  if (rulesStatus !== 200 || !Array.isArray(rulesJson)) return 'unknown';
292	  return rulesJson.some((r) => GATING_RULE_TYPES.includes(r?.type)) ? 'present' : 'absent';
293	}
294	
295	export async function readMergeGate(token, repo, base) {
296	  const branch = await gh(token, `/repos/${repo}/branches/${encodeURIComponent(base)}`);
297	  const rules = await gh(token, `/repos/${repo}/rules/branches/${encodeURIComponent(base)}`);
298	  return classifyMergeGate({
299	    branchStatus: branch.status, branchJson: branch.json,
300	    rulesStatus: rules.status, rulesJson: rules.json,
301	  });
302	}
303	
304	// --- judging a PR by the runs on its head (#455/#205/#95) ---------------------
305	// Arming is best-effort and can fail PERMANENTLY, so "arm and move on" is not a
306	// delivery guarantee. Two shapes, both observed across the fleet, both leaving a
307	// green PR open forever:
308	//
309	//   1. GATED CI. GitHub CREATES the pull_request run for a GITHUB_TOKEN push and
310	//      parks it at conclusion `action_required`, pending a human "Approve and
311	//      run" that nobody is watching for. The run never executes, so it never
312	//      reports; `enablePullRequestAutoMerge` then refuses the PR with "in
313	//      unstable status (required checks are failing)". Meanwhile the
314	//      workflow_dispatch run started on the SAME head sha ran and passed. So CI
315	//      did pass; only the phantom gated run says otherwise.
316	//   2. AUTO-MERGE OFF. The repo never enabled Settings → General → "Allow
317	//      auto-merge", so the mutation is rejected outright no matter how green.
318	//
319	// Both are settled by the same evidence: the runs on the PR's own head sha. If
320	// CI has CONCLUDED and nothing actually failed, the content on that sha is
321	// verified and `auto-merge` means merge it. A gated `action_required` run is not
322	// a failure — it is a run that never happened.
323	//
324	// Deliberately conservative about MERGING, because that bypasses the arm:
325	//   - Anything still queued/running → `wait`. Never merge mid-flight.
326	//   - Any real failure (failure / timed_out / cancelled / startup_failure), or no
327	//     successful run to stand on → `close`: NOT a merge, and equally not a reuse.
328	//     (What `close` means is the CALLER's policy — a delivery closes and re-cuts
329	//     its per-cycle branch; a landing pass just leaves the PR standing.)
330	//
331	// A `review` member's PR is the owner's to act on, on their own clock — never
332	// merged, and never closed out from under them either.
333	export const REAL_FAILURES = ['failure', 'timed_out', 'cancelled', 'startup_failure'];
334	
335	export function pullDisposition({ delivery, runs }) {
336	  if (delivery !== 'auto-merge') return 'keep';
337	  const list = (runs ?? []).filter(Boolean);
338	  if (list.some((r) => r.status !== 'completed')) return 'wait';
339	  if (list.some((r) => REAL_FAILURES.includes(r.conclusion))) return 'close';
340	  if (!list.some((r) => r.conclusion === 'success')) return 'close';
341	  return 'merge';
342	}
343	
344	// Why the merge had to happen here rather than through the arm. The log line has
345	// to name which shape this was, or the repo misconfiguration behind it stays
346	// invisible — and it is a REPO setting, so only a human can retire it.
347	export function mergeReason(runs) {
348	  // The no-remedy shape names no setting (#677): on a base that requires
349	  // nothing, landing here IS the design, and sending an owner to fix something
350	  // already correct is worse than saying nothing.
351	  return (runs ?? []).some((r) => r?.conclusion === 'action_required')
352	    ? 'its pull_request run is parked at action_required (never ran) while the dispatched run passed'
353	    + ' — check Settings → Actions → General → workflow-approval requirements'
354	    : 'its dispatched checks concluded green and nothing on the base branch queues an auto-merge';
355	}
356	
357	// Why a PR was left (or closed) rather than merged — the same visibility
358	// argument, for the case that matters more: a member whose CI is genuinely red.
359	export function failureSummary(runs) {
360	  const list = (runs ?? []).filter(Boolean);
361	  const failed = list.filter((r) => REAL_FAILURES.includes(r?.conclusion));
362	  if (failed.length) return `failing CI: ${failed.map((r) => `${r.name} ${r.conclusion}`).join(', ')}`;
363	  // A run still going at the bound is a statement about the CLOCK, not a verdict
364	  // on the runs, and conflating the two sent a reader to a repository-settings
365	  // diagnosis for a repo where nothing was misconfigured (#1026). Name what is
366	  // still moving, so a member whose CI outruns the budget is visible as itself.
367	  const inFlight = list.filter((r) => r?.status && r.status !== 'completed');
368	  if (inFlight.length) {
369	    return 'still running at the landing bound: '
370	      + `${inFlight.map((r) => `${r.name} ${r.status}`).join(', ')} — it lands next cycle`;
371	  }
372	  return 'no successful run on its head sha';
373	}
374	
375	// --- disposing of the PREVIOUS cycle's delivery (#787) ------------------------
376	// A task that delivers on a per-cycle branch must dispose of the last cycle's PR
377	// before cutting its own, or the two accumulate: the incumbent can no longer merge
378	// (its diff is landed by the newcomer) and nothing else will ever close it.
379	//
380	// Found by head-branch PREFIX, because the name carries a per-cycle date and seed —
381	// the prefix is what identifies the family. The whole PR is returned rather than its
382	// ref alone: disposal needs its number and head sha.
383	export function openDeliveredPull(pulls, prefix) {
384	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
385	}
386	
387	// The I/O half: read the runs on that PR's head, decide with the SAME predicate the
388	// landing poll uses, and either merge it (its content was verified — only the arm
389	// failed) or close it and delete its branch so this cycle re-cuts from scratch.
390	//
391	// Returns which disposal happened, because the three outcomes leave the caller in
392	// three different places and a bare null conflates two of them:
393	//
394	//   'kept'   — it still stands (a `wait`, a `review` member, or a failed attempt).
395	//              Do not deliver on top of it; leaving ONE PR alive is the whole point.
396	//   'closed' — the way is clear and main is unchanged, so this cycle re-cuts.
397	//   'merged' — the way is clear but MAIN JUST MOVED, and this job's checkout predates
398	//              it. Converging on that stale tree would re-deliver a diff already on
399	//              main, which GitHub refuses ("No commits between…") and which would in
400	//              any case be the duplicate this whole helper exists to prevent. The
401	//              caller ends its cycle instead; the next one starts from fresh main.
402	//
403	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it was
404	// found, because a cycle that cannot dispose of the incumbent must skip rather than
405	// pile a second PR on top of it.
406	export async function disposeOpenPull({ token, repo, pr, delivery, log = console.log }) {
407	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
408	  if (status !== 200) {
409	    log(`could not read the runs for PR #${pr.number}'s head (HTTP ${status}) — leaving it`);
410	    return 'kept';
411	  }
412	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
413	  const disposition = pullDisposition({ delivery, runs });
414	
415	  if (disposition === 'keep' || disposition === 'wait') {
416	    log(`keeping PR #${pr.number} (${disposition})`);
417	    return 'kept';
418	  }
419	
420	  if (disposition === 'merge') {
421	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
422	      method: 'PUT', body: { merge_method: 'squash' },
423	    });
424	    if (res.status === 200) {
425	      log(`merged PR #${pr.number} — ${mergeReason(runs)}`);
426	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
427	      return 'merged';
428	    }
429	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
430	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
431	  }
432	
433	  // Closed, not left to rot: whatever went wrong on that head, the next converge
434	  // reproduces the same content from the same inputs. Named in the log because a
435	  // member closing its delivery every single cycle is a repo whose CI needs a human,
436	  // and the pattern has to be visible to be noticed.
437	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
438	  if (closed.status !== 200) {
439	    log(`could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
440	    return 'kept';
441	  }
442	  log(`closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
443	  await deleteBranch({ token, repo, ref: pr.head?.ref, log });
444	  return 'closed';
445	}
446	
447	// --- landing THIS run's PR when the arm could not (#649) ----------------------
448	// On a member whose pull_request run is gated, EVERY arm fails; deferring to the
449	// next cycle's disposal put a standing ~24h offset between a task's output and
450	// that member's main. The evidence that settles it does not take a day to
451	// arrive: the dispatched run this delivery just started concludes in minutes at
452	// worst. So we wait for it, once, and merge on exactly the reasoning disposal
453	// uses. Same decision, made now.
454	//
455	// Bounded and cheap because it only runs where the arm ALREADY failed (or was
456	// skipped as doomed): a healthy member arms and returns without waiting at all.
457	//
458	// TWO BOUNDS, because the poll waits on two different things and one number
459	// answered both wrongly (#1026). Nothing VISIBLE is the short case: a dispatch
460	// that has registered no run is a dispatch that may never register one, so
461	// waiting long buys nothing. A run we can see EXECUTING is the opposite — the
462	// evidence is on its way and the only question is whether the prework budget
463	// outlasts it. Collapsed into one 180s bound, a member whose slowest check took
464	// 3m29s had its green PR abandoned 26s short every cycle and landed a day late
465	// by the next cycle's disposal, which is exactly the offset #649 closed.
466	//
467	// The in-flight bound is ceilinged by the PREWORK budget it spends, not by what
468	// CI might take: the shortest `prework_timeout` among the merged-pr tasks is
469	// 600s, and the poll is the tail of a prework that has already converged a tree
470	// and opened a PR. 300s leaves that preamble its room. A member whose CI outruns
471	// even this still lands next cycle — but now it SAYS so (failureSummary below),
472	// where before the give-up was indistinguishable from a red repo.
473	export const LAND_TIMEOUT_MS = 180_000;
474	export const LAND_INFLIGHT_TIMEOUT_MS = 300_000;
475	export const LAND_POLL_MS = 5_000;
476	
477	// What one poll of the head sha's runs says to do: `merge`, `poll` again, or
478	// `give-up` and leave the PR standing.
479	//
480	// It NEVER closes. A cycle's disposal may close a PR because that PR is LAST
481	// cycle's and this cycle is about to re-cut it; here the PR IS this run's
482	// delivery, and closing it would throw away the work that just ran. A red member
483	// therefore leaves its PR open for the next run (or a human) to dispose of.
484	// `expected` is how many verification runs THIS delivery dispatched on the head
485	// seconds ago. Fewer visible runs than that is the API still registering them —
486	// a POLL, never a verdict. Without it, the first read 0.3s after the dispatch
487	// found an empty list and judged "nothing will ever verify this", stranding
488	// seven members' green PRs in one forced fleet pass (2026-08-07).
489	export function landAttempt({
490	  delivery, runs, expected = 0, elapsedMs = 0,
491	  timeoutMs = LAND_TIMEOUT_MS, inflightTimeoutMs = LAND_INFLIGHT_TIMEOUT_MS,
492	}) {
493	  if ((runs ?? []).length < expected) return elapsedMs >= timeoutMs ? 'give-up' : 'poll';
494	  const disposition = pullDisposition({ delivery, runs });
495	  if (disposition === 'merge') return 'merge';
496	  // `wait` is precisely "a run is not `completed`" — the seen-it-executing case,
497	  // which gets the longer budget.
498	  if (disposition === 'wait') return elapsedMs >= inflightTimeoutMs ? 'give-up' : 'poll';
499	  return 'give-up';
500	}
501	
502	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
503	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
504	export async function enableAutoMerge(token, pullRequestId) {
505	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
506	  const res = await fetch(`${API}/graphql`, {
507	    method: 'POST',
508	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
509	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
510	  });
511	  const json = await res.json().catch(() => null);
512	  if (json?.errors?.length) throw new Error(json.errors[0].message);
513	}
514	
515	// Tidy the ref behind a merged (or disposed) PR — a dead branch left on the
516	// remote is litter that accumulates one per run. Never fatal: the branch is not
517	// the deliverable.
518	export async function deleteBranch({ token, repo, ref, log = console.log }) {
519	  if (!ref) return;
520	  const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
521	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
522	}
523	
524	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
525	
526	// The I/O half of same-run landing: poll this PR's head sha until its runs have
527	// concluded, then merge on the same evidence disposal would use a cycle later.
528	// Returns true iff it merged. Best-effort throughout — every failure path leaves
529	// the PR exactly as the arm left it, which is what the next run expects.
530	export async function landNow({ token, repo, pr, delivery, expected = 0, log = console.log }) {
531	  const started = Date.now();
532	  for (;;) {
533	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
534	    if (status !== 200) {
535	      log(`could not read this run's checks for PR #${pr.number} (HTTP ${status}) — leaving it for the next run`);
536	      return false;
537	    }
538	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
539	    const attempt = landAttempt({ delivery, runs, expected, elapsedMs: Date.now() - started });
540	
541	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
542	    if (attempt === 'give-up') {
543	      log(`PR #${pr.number} not landable this run (${failureSummary(runs)})`
544	        + ' — leaving it open for the next run to dispose of');
545	      return false;
546	    }
547	
548	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
549	      method: 'PUT', body: { merge_method: 'squash' },
550	    });
551	    if (res.status === 200) {
552	      log(`merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
553	      await deleteBranch({ token, repo, ref: pr.head?.ref, log });
554	      return true;
555	    }
556	    log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
557	      + ' — leaving it for the next run');
558	    return false;
559	  }
560	}
561	
562	// The whole landing, composed — what a task's delivery calls once its PR exists.
563	// Dispatch the PR's checks (they establish `hasPrCi`, the fact deliveryAction
564	// turns on), read what the base requires, then merge / land / arm per the
565	// decision — with the landing poll as fallback for a failed arm. `pr` must carry
566	// the CURRENT head ({ number, node_id, head: { ref, sha } }): after a force-push,
567	// a stale sha polls runs that will never conclude.
568	//
569	// Returns { merged, action }. `action: 'none'` is the review member — the PR
570	// stands, deliberately, and that is a delivered outcome, not a failure.
571	export async function landDelivery({ token, repo, base, pr, delivery, log = console.log }) {
572	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open emitted no
573	  // pull_request event, so without this the PR has no runs (#565). AFTER the
574	  // push, so the dispatched runs execute the branch's own head. Best-effort: a
575	  // dispatch failure must not fail the delivery that was already pushed. Run for
576	  // review members too — their owner wants green checks to review against.
577	  const ci = await dispatchCiRuns({ token, repo, branch: pr.head?.ref, log })
578	    .catch((e) => { log(`CI dispatch on ${pr.head?.ref} failed: ${e.message}`); return null; });
579	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
580	  // How many verification runs this delivery ACTUALLY started on the head — what
581	  // the landing poll waits to see registered before it judges anything
582	  // (landAttempt). `started`, never the plan: a rejected dispatch POST starts
583	  // nothing, and waiting on the plan wedges the poll against a run that can
584	  // never come.
585	  const expected = ci?.started?.length ?? 0;
586	
587	  const gate = await readMergeGate(token, repo, base).catch(() => 'unknown');
588	  const action = deliveryAction({ delivery, hasPrCi, gate });
589	  let merged = false;
590	
591	  if (action === 'merge') {
592	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
593	      method: 'PUT', body: { merge_method: 'squash' },
594	    });
595	    if (res.status === 200) { merged = true; log(`merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
596	    else log(`could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
597	  } else if (action === 'land') {
598	    // The base requires nothing, so auto-merge has no queue to wait behind and
599	    // the arm mutation would be rejected "clean status" — every run, no setting
600	    // to fix (#677). Skip the doomed arm; wait for this run's own dispatched
601	    // evidence and land on it. Delivery must land every cycle, not heal next cycle.
602	    log(`${base} requires nothing to merge — skipping the doomed auto-merge arm;`
603	      + ` waiting for this run's ${expected} dispatched run(s) and landing PR #${pr.number} here`);
604	    merged = await landNow({ token, repo, pr, delivery, expected, log });
605	  } else if (action === 'arm' && pr.node_id) {
606	    // Surfaced, not swallowed: a failed arm is why a delivered PR sits open
607	    // forever, and the two usual causes are both fixable repo settings.
608	    const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
609	      .catch((e) => {
610	        log(`could not arm auto-merge on PR #${pr.number}: ${e.message}`
611	          + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
612	          + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
613	          + ' Waiting for this run\'s dispatched checks and landing it here.');
614	        return false;
615	      });
616	    // Only where the arm failed. A member that armed is GitHub's to land, and
617	    // waiting on it here would add a poll to every healthy repo for nothing.
618	    if (!armed) merged = await landNow({ token, repo, pr, delivery, expected, log });
619	  }
620	  return { merged, action };
621	}
622

